package com.example.melonstools.data;
import com.example.melonstools.department.DepartmentPolicy;import com.google.gson.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.level.saveddata.SavedData;import java.util.*;
/** Phase 4-C audited dispatches. */
public class DispatchSavedData extends SavedData{public static final String DATA_NAME="melon_dispatches";public static final String PENDING="pending",ACKNOWLEDGED="acknowledged",COMPLETED="completed",CANCELLED="cancelled";private final List<Dispatch> items=new ArrayList<>();private int sequence;public static DispatchSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(DispatchSavedData::load,DispatchSavedData::new,DATA_NAME);}public static DispatchSavedData load(CompoundTag tag){DispatchSavedData d=new DispatchSavedData();d.sequence=tag.getInt("Sequence");ListTag a=tag.getList("Items",Tag.TAG_COMPOUND);for(int i=0;i<a.size();i++)d.items.add(Dispatch.load(a.getCompound(i)));return d;}@Override public CompoundTag save(CompoundTag tag){tag.putInt("Sequence",sequence);ListTag a=new ListTag();for(Dispatch x:items)a.add(x.save());tag.put("Items",a);return tag;}private Dispatch byId(String id){for(Dispatch d:items)if(d.id.equals(id))return d;return null;}private static String s(String v){return v==null?"":v.trim();}private static boolean has(String csv,String u){return Arrays.asList(csv.split(",")).contains(u);}private static String add(String csv,String u){return u==null||u.isBlank()||has(csv,u)?csv:(csv==null||csv.isBlank()?u:csv+","+u);}private static void audit(ServerPlayer p,String a,String id,boolean ok,String why,String after){OperationAuditSavedData.get(p.serverLevel()).record(p,a,id,ok?"ok":"denied",why,"",after);}private static boolean target(DepartmentPolicy.Identity u,Dispatch d){return (d.targetDepartment.isBlank()||u.department().equals(d.targetDepartment))&&(d.targetPosition.isBlank()||u.position().equals(d.targetPosition))&&u.level()>=d.minLevel;}
 public Dispatch create(ServerPlayer p,JsonObject o){DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);boolean op=p.hasPermissions(2);String target=DepartmentPolicy.normalizeDepartment(o.has("targetDepartment")?o.get("targetDepartment").getAsString():u.department());boolean ok=DepartmentPolicy.canCreateDispatch(u.department(),u.position(),u.level(),target,op);if(!ok){audit(p,"dispatch_create","",false,"permission","");return null;}Dispatch d=new Dispatch();d.id="dispatch-"+(++sequence);d.status=PENDING;d.sourceDepartment=u.department();d.targetDepartment=target;d.targetPosition=s(o.has("targetPosition")?o.get("targetPosition").getAsString():"");d.minLevel=o.has("minLevel")?Math.max(0,o.get("minLevel").getAsInt()):0;d.priority=s(o.has("priority")?o.get("priority").getAsString():"normal");d.message=s(o.has("message")?o.get("message").getAsString():"");d.location=s(o.has("location")?o.get("location").getAsString():"");d.createdByUuid=p.getUUID().toString();d.createdByName=p.getScoreboardName();d.createdAt=d.updatedAt=System.currentTimeMillis();items.add(d);setDirty();audit(p,"dispatch_create",d.id,true,"target="+target,d.status);return d;} public boolean ack(ServerPlayer p,String id,boolean complete){Dispatch d=byId(id);String u=p.getUUID().toString();boolean ok=d!=null&&(PENDING.equals(d.status)||ACKNOWLEDGED.equals(d.status))&&(target(DepartmentPolicy.identity(p),d)||has(d.participantUuids,u)||u.equals(d.createdByUuid));if(ok){d.participantUuids=add(d.participantUuids,u);d.status=complete?COMPLETED:ACKNOWLEDGED;d.receipt=p.getScoreboardName()+":"+d.status;d.updatedAt=System.currentTimeMillis();setDirty();}audit(p,complete?"dispatch_completed":"dispatch_ack",id,ok,"target_or_receiver",ok?d.status:"");return ok;}public boolean cancel(ServerPlayer p,String id,String reason){Dispatch d=byId(id);boolean ok=d!=null&&(p.hasPermissions(2)||p.getUUID().toString().equals(d.createdByUuid));if(ok){d.status=CANCELLED;d.receipt=s(reason);d.updatedAt=System.currentTimeMillis();setDirty();}audit(p,"dispatch_cancel",id,ok,"sender_only",ok?d.status:"");return ok;}
 public JsonObject toJsonFor(ServerPlayer v){DepartmentPolicy.Identity u=DepartmentPolicy.identity(v);boolean all=v.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level());JsonObject r=new JsonObject();JsonArray a=new JsonArray();String uuid=v.getUUID().toString();for(Dispatch d:items)if(all||target(u,d)||has(d.participantUuids,uuid)||uuid.equals(d.createdByUuid))a.add(d.toJson());r.add("items",a);r.addProperty("skeleton",false);return r;}public static class Dispatch{public String id="",status=PENDING,priority="normal",sourceDepartment="",targetDepartment="",targetPosition="",participantUuids="",message="",receipt="",createdByUuid="",createdByName="",location="";public int minLevel;public long createdAt,updatedAt,dueAt;CompoundTag save(){CompoundTag t=new CompoundTag();t.putString("Id",id);t.putString("Status",status);t.putString("Priority",priority);t.putString("SourceDepartment",sourceDepartment);t.putString("TargetDepartment",targetDepartment);t.putString("TargetPosition",targetPosition);t.putInt("MinLevel",minLevel);t.putString("ParticipantUuids",participantUuids);t.putString("Message",message);t.putString("Receipt",receipt);t.putString("Location",location);t.putString("CreatedByUuid",createdByUuid);t.putString("CreatedByName",createdByName);t.putLong("CreatedAt",createdAt);t.putLong("UpdatedAt",updatedAt);t.putLong("DueAt",dueAt);return t;}static Dispatch load(CompoundTag t){Dispatch d=new Dispatch();d.id=t.getString("Id");d.status=t.getString("Status");d.priority=t.getString("Priority");d.sourceDepartment=t.getString("SourceDepartment");d.targetDepartment=t.getString("TargetDepartment");d.targetPosition=t.getString("TargetPosition");d.minLevel=t.getInt("MinLevel");d.participantUuids=t.getString("ParticipantUuids");d.message=t.getString("Message");d.receipt=t.getString("Receipt");d.location=t.getString("Location");d.createdByUuid=t.getString("CreatedByUuid");d.createdByName=t.getString("CreatedByName");d.createdAt=t.getLong("CreatedAt");d.updatedAt=t.getLong("UpdatedAt");d.dueAt=t.getLong("DueAt");return d;}JsonObject toJson(){JsonObject o=new JsonObject();o.addProperty("id",id);o.addProperty("status",status);o.addProperty("priority",priority);o.addProperty("sourceDepartment",sourceDepartment);o.addProperty("targetDepartment",targetDepartment);o.addProperty("targetPosition",targetPosition);o.addProperty("minLevel",minLevel);o.addProperty("message",message);o.addProperty("receipt",receipt);o.addProperty("location",location);o.addProperty("createdByName",createdByName);o.addProperty("participantUuids",participantUuids);o.addProperty("updatedAt",updatedAt);return o;}}}
